class PersonBuilder {
    var name: String? = null
    var age: Int? = null
    fun build(): Person {
        return Person(name!!, age!!)
    }
}
fun person(init: PersonBuilder.() -> Unit): Person {
    val builder = PersonBuilder()
    builder.init()
    return builder.build()
}
fun main() {
    val person = person {
        name = "John"
        age = 30
    }
    println(person)
}

